"""Add read-only stock balances and inbound delivery projections.

Source records remain authoritative; portal reads and writes keep their current paths.
"""
from alembic import op

revision = '0008_proc_inventory'
down_revision = '0007_proc_fulfillment'
branch_labels = None
depends_on = None

SQL = "-- Inventory projections follow authoritative records in the same transaction.\n-- Reservations may include inbound supply; reserved <= usable is not required.\nCREATE TABLE public.proc_stock (\n    tenant varchar(64) NOT NULL,\n    id varchar(64) NOT NULL,\n    source_revision integer NOT NULL CHECK (source_revision>=1),\n    sku varchar(80) NOT NULL CHECK (length(sku)>0),\n    usable integer NOT NULL CHECK (usable>=0),\n    reserved integer NOT NULL CHECK (reserved>=0),\n    quarantine integer NOT NULL CHECK (quarantine>=0),\n    as_of timestamptz NOT NULL CHECK (isfinite(as_of)),\n    source text NOT NULL,\n    PRIMARY KEY (tenant,id)\n);\nCREATE TABLE public.proc_stock_inbound (\n    tenant varchar(64) NOT NULL,\n    stock_id varchar(64) NOT NULL,\n    line_index integer NOT NULL CHECK (line_index>=0),\n    quantity integer NOT NULL CHECK (quantity>0),\n    confirmed boolean NOT NULL,\n    due_date date NOT NULL CHECK (isfinite(due_date)),\n    source_snapshot jsonb NOT NULL CHECK (jsonb_typeof(source_snapshot)='object'),\n    PRIMARY KEY (tenant,stock_id,line_index),\n    FOREIGN KEY (tenant,stock_id) REFERENCES public.proc_stock(tenant,id)\n        DEFERRABLE INITIALLY DEFERRED\n);\nCREATE INDEX ix_proc_stock_sku ON public.proc_stock(tenant,sku);\nCREATE INDEX ix_proc_stock_inbound_due ON public.proc_stock_inbound(tenant,stock_id,due_date);\nDO $$ DECLARE t text;\nBEGIN\n    FOREACH t IN ARRAY ARRAY['proc_stock','proc_stock_inbound'] LOOP\n        EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);\n        EXECUTE format('ALTER TABLE public.%I FORCE ROW LEVEL SECURITY',t);\n        EXECUTE format('CREATE POLICY tenant_scope ON public.%I TO supplypilot_app USING (tenant=NULLIF(current_setting(''supplypilot.tenant'',true),'''')) WITH CHECK (tenant=NULLIF(current_setting(''supplypilot.tenant'',true),''''))',t);\n        EXECUTE format('CREATE POLICY migration_owner ON public.%I TO supplypilot_migrator USING (true) WITH CHECK (true)',t);\n        EXECUTE format('REVOKE ALL ON TABLE public.%I FROM PUBLIC,supplypilot_app',t);\n        EXECUTE format('GRANT SELECT ON TABLE public.%I TO supplypilot_app',t);\n    END LOOP;\nEND $$;\n\nCREATE FUNCTION public.sync_procurement_stock()\nRETURNS trigger LANGUAGE plpgsql SECURITY DEFINER\nSET search_path=pg_catalog,pg_temp\nAS $$ DECLARE d jsonb; entry jsonb; key text;\nBEGIN\n    IF TG_OP='UPDATE' AND (OLD.kind='stock' OR NEW.kind='stock') AND\n       (OLD.tenant,OLD.id,OLD.kind) IS DISTINCT FROM (NEW.tenant,NEW.id,NEW.kind) THEN\n        RAISE EXCEPTION 'Inventory identity, tenant and kind are immutable' USING ERRCODE='23514';\n    END IF;\n    IF TG_OP='DELETE' THEN\n        IF OLD.kind='stock' THEN\n            DELETE FROM public.proc_stock_inbound WHERE tenant=OLD.tenant AND stock_id=OLD.id;\n            DELETE FROM public.proc_stock WHERE tenant=OLD.tenant AND id=OLD.id;\n        END IF;\n        RETURN OLD;\n    END IF;\n    IF NEW.kind<>'stock' THEN RETURN NEW; END IF;\n    d:=NEW.data::jsonb;\n    IF jsonb_typeof(d) IS DISTINCT FROM 'object' OR\n       jsonb_typeof(d->'sku') IS DISTINCT FROM 'string' OR\n       jsonb_typeof(d->'as_of') IS DISTINCT FROM 'string' OR\n       jsonb_typeof(d->'source') IS DISTINCT FROM 'string' THEN\n        RAISE EXCEPTION 'Inventory requires SKU, timestamp and source strings' USING ERRCODE='23514';\n    END IF;\n    FOREACH key IN ARRAY ARRAY['usable','reserved','quarantine'] LOOP\n        IF jsonb_typeof(d->key) IS DISTINCT FROM 'number' THEN\n            RAISE EXCEPTION 'Inventory balances must be integers' USING ERRCODE='23514';\n        END IF;\n        IF (d->>key)::numeric<>trunc((d->>key)::numeric) THEN\n            RAISE EXCEPTION 'Inventory balances must be integers' USING ERRCODE='23514';\n        END IF;\n    END LOOP;\n    IF jsonb_typeof(COALESCE(d->'inbound','[]'::jsonb)) IS DISTINCT FROM 'array' THEN\n        RAISE EXCEPTION 'Inventory inbound deliveries must be an array' USING ERRCODE='23514';\n    END IF;\n    FOR entry IN SELECT value FROM jsonb_array_elements(COALESCE(d->'inbound','[]'::jsonb)) LOOP\n        IF jsonb_typeof(entry) IS DISTINCT FROM 'object' OR\n           jsonb_typeof(entry->'quantity') IS DISTINCT FROM 'number' OR\n           jsonb_typeof(entry->'confirmed') IS DISTINCT FROM 'boolean' OR\n           jsonb_typeof(entry->'date') IS DISTINCT FROM 'string' THEN\n            RAISE EXCEPTION 'Inbound deliveries require integer quantity, boolean confirmation and date' USING ERRCODE='23514';\n        END IF;\n        IF (entry->>'quantity')::numeric<>trunc((entry->>'quantity')::numeric) OR\n           (entry->>'date') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN\n            RAISE EXCEPTION 'Inbound deliveries require integer quantity and ISO date' USING ERRCODE='23514';\n        END IF;\n    END LOOP;\n    INSERT INTO public.proc_stock VALUES(NEW.tenant,NEW.id,NEW.revision,d->>'sku',\n        (d->>'usable')::integer,(d->>'reserved')::integer,(d->>'quarantine')::integer,\n        (d->>'as_of')::timestamptz,d->>'source')\n    ON CONFLICT(tenant,id) DO UPDATE SET source_revision=EXCLUDED.source_revision,\n        sku=EXCLUDED.sku,usable=EXCLUDED.usable,reserved=EXCLUDED.reserved,\n        quarantine=EXCLUDED.quarantine,as_of=EXCLUDED.as_of,source=EXCLUDED.source;\n    DELETE FROM public.proc_stock_inbound WHERE tenant=NEW.tenant AND stock_id=NEW.id;\n    INSERT INTO public.proc_stock_inbound\n    SELECT NEW.tenant,NEW.id,(x.n-1)::integer,(x.v->>'quantity')::integer,\n        (x.v->>'confirmed')::boolean,(x.v->>'date')::date,x.v\n    FROM jsonb_array_elements(COALESCE(d->'inbound','[]'::jsonb)) WITH ORDINALITY x(v,n);\n    RETURN NEW;\nEND $$;\nREVOKE ALL ON FUNCTION public.sync_procurement_stock() FROM PUBLIC,supplypilot_app;\nCREATE TRIGGER records_inventory_sync AFTER INSERT OR UPDATE OR DELETE ON public.records\nFOR EACH ROW EXECUTE FUNCTION public.sync_procurement_stock();\nUPDATE public.records SET data=data WHERE kind='stock';\n"


def upgrade():
    op.execute(SQL)


def downgrade():
    raise RuntimeError('Restore a reviewed backup; automatic inventory projection removal is disabled.')
